using System.Data;using System.Text;using Dapper;using Microsoft.Data.SqlClient;using Microsoft.Extensions.Configuration;using GraphApi.Models.SGR.Menus;namespace GraphApi.Services.SGR.Menus{    public class MenusService : IMenusService    {        private readonly IDbConnection   _objDbDefault;        private readonly IConfiguration  _objConfig;        public MenusService(IDbConnection objDbDefault, IConfiguration objConfig)        {            _objDbDefault = objDbDefault;            _objConfig    = objConfig;        }        public async Task<IEnumerable<clReadMenus>> GetMenus(            int userId,            string windowName)        {            var vSql = new StringBuilder($@"                --WindowName:{windowName},UserID:{userId}                SELECT  *                 FROM sgr.Menus (NOLOCK)            ");            var vParameters = new DynamicParameters();            var vList = await _objDbDefault.QueryAsync<clReadMenus>(vSql.ToString(), vParameters);            return vList;        }        public async Task<IEnumerable<dynamic>> GetMenusDynamic(            int? menuID,            string? tituloMenu,            string? ruta,            string? icono,            int? orden,            int? padreMenuID,            bool? bEliminado,            string? columnNames,            int userId,            string windowName)        {            string sColumnNames = string.IsNullOrWhiteSpace(columnNames) ? "MenuID, TituloMenu, Ruta, Icono, Orden, PadreMenuID, bEliminado" : columnNames;            var vSql = new StringBuilder($@"                --WindowName:{windowName},UserID:{userId}                SELECT {sColumnNames}                FROM sgr.Menus (NOLOCK)                WHERE 1=1            ");            var vParameters = new DynamicParameters();            if (menuID.HasValue)            {                vSql.Append(" AND MenuID = @MenuID");                vParameters.Add("MenuID",menuID);            }            if (!string.IsNullOrWhiteSpace(tituloMenu))            {                vSql.Append(" AND TituloMenu LIKE @TituloMenu");                vParameters.Add("TituloMenu",$"%{tituloMenu}%");            }            if (!string.IsNullOrWhiteSpace(ruta))            {                vSql.Append(" AND Ruta LIKE @Ruta");                vParameters.Add("Ruta",$"%{ruta}%");            }            if (!string.IsNullOrWhiteSpace(icono))            {                vSql.Append(" AND Icono LIKE @Icono");                vParameters.Add("Icono",$"%{icono}%");            }            if (bEliminado.HasValue)            {                vSql.Append(" AND bEliminado = @bEliminado");                vParameters.Add("bEliminado", bEliminado.Value);            }            var vList = await _objDbDefault.QueryAsync<dynamic>(vSql.ToString(), vParameters);            return vList;        }        public async Task<clReadMenus> CreateMenus(clCreateMenus objInput, int userId, string windowName)        {            string sInsertSql = $@"                --WindowName:{windowName},UserID:{userId}                INSERT INTO sgr.Menus                (TituloMenu, Ruta, Icono, Orden, PadreMenuID, bEliminado, Creado, UsuarioCreacionID, FechaCreacion)                VALUES (@TituloMenu, @Ruta, @Icono, @Orden, @PadreMenuID, @bEliminado, @Creado, @UsuarioCreacionID, GETDATE());                SELECT CAST(SCOPE_IDENTITY() AS INT);            ";            var vInsertParams = new            {                objInput.TituloMenu,                objInput.Ruta,                objInput.Icono,                objInput.Orden,                objInput.PadreMenuID,                objInput.bEliminado,                Creado     = windowName,                UsuarioCreacionID = userId            };            var vNewId = await _objDbDefault.ExecuteScalarAsync<int>(sInsertSql, vInsertParams);            string sSelectSql = @"                SELECT MenuID, TituloMenu, Ruta, Icono, Orden, PadreMenuID, bEliminado                FROM sgr.Menus (NOLOCK)                WHERE MenuID = @MenuID;";            var vReadParams = new { MenuID = vNewId };            var vCreated = await _objDbDefault.QuerySingleOrDefaultAsync<clReadMenus>(sSelectSql, vReadParams);            if (vCreated is null) throw new InvalidOperationException($"No se pudo recuperar el Menu con ID {vNewId}.");            return vCreated;        }        public async Task<clReadMenus?> UpdateMenus(clUpdateMenus objInput, int userId, string windowName)        {            var vSets = new List<string>();            var vParameters = new DynamicParameters();            vParameters.Add("MenuID", objInput.MenuID);            if (objInput.TituloMenu is not null)            {                vSets.Add("TituloMenu = @TituloMenu");                vParameters.Add("TituloMenu", objInput.TituloMenu);            }            if (objInput.Ruta is not null)            {                vSets.Add("Ruta = @Ruta");                vParameters.Add("Ruta", objInput.Ruta);            }            if (objInput.Icono is not null)            {                vSets.Add("Icono = @Icono");                vParameters.Add("Icono", objInput.Icono);            }            if (objInput.Orden != null)            {                vSets.Add("Orden = @Orden");                vParameters.Add("Orden", objInput.Orden);            }            if (objInput.PadreMenuID != null)            {                vSets.Add("PadreMenuID = @PadreMenuID");                vParameters.Add("PadreMenuID", objInput.PadreMenuID);            }            if (objInput.bEliminado != null)            {                vSets.Add("bEliminado = @bEliminado");                vParameters.Add("bEliminado", objInput.bEliminado);            }            vSets.Add($"Modificado = '{windowName}'");            vSets.Add($"UsuarioModificacionID = {userId}");            vSets.Add("FechaModificacion = GETDATE()");            var vSetClause = string.Join(", ", vSets);            var sSql = $@"                --WindowName:{windowName},UserID:{userId}                UPDATE sgr.Menus                SET {vSetClause}                WHERE MenuID = @MenuID;";            var vAffected = await _objDbDefault.ExecuteAsync(sSql, vParameters);            if (vAffected == 0) return null;            const string sSelect = @"                SELECT MenuID, TituloMenu, Ruta, Icono, Orden, PadreMenuID, bEliminado                FROM sgr.Menus (NOLOCK)                WHERE MenuID = @MenuID;";            return await _objDbDefault.QueryFirstOrDefaultAsync<clReadMenus>(sSelect, new {  objInput.MenuID });        }        public async Task<bool> DeleteMenus(int nMenusID)        {            const string sSql = @"                DELETE FROM sgr.Menus                WHERE MenuID = @Id;";            var vAffected = await _objDbDefault.ExecuteAsync(sSql, new { Id = nMenusID });            return vAffected > 0;        }    }}